#include <iostream>

int main() {
    int i = 4;
    int old = i++;
    int next = ++i;
    int larger = (old > next) ? old : next;
    std::cout << old << ' ' << next << ' ' << i << ' ' << larger << ' ' << sizeof(char) << '\n';
    return 0;
}

